-- 100_project_quality_closeout.sql
BEGIN;
ALTER TABLE public.snags ADD COLUMN IF NOT EXISTS work_ontology_version_id uuid,ADD COLUMN IF NOT EXISTS work_group_id uuid;
ALTER TABLE public.snags DROP CONSTRAINT IF EXISTS snags_work_group_pair_check;ALTER TABLE public.snags ADD CONSTRAINT snags_work_group_pair_check CHECK((work_ontology_version_id IS NULL)=(work_group_id IS NULL))NOT VALID;
ALTER TABLE public.snags DROP CONSTRAINT IF EXISTS snags_work_group_fkey;ALTER TABLE public.snags ADD CONSTRAINT snags_work_group_fkey FOREIGN KEY(work_ontology_version_id,work_group_id)REFERENCES public.work_ontology_work_groups(ontology_version_id,id)ON DELETE RESTRICT NOT VALID;
CREATE INDEX IF NOT EXISTS snags_project_work_group_idx ON public.snags(project_id,work_group_id)WHERE work_group_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS public.project_quality_closeout_versions(
 id uuid PRIMARY KEY,project_id bigint NOT NULL REFERENCES public.projects(id)ON DELETE RESTRICT,version_number integer NOT NULL CHECK(version_number>0),status text NOT NULL CHECK(status IN('DRAFT','CONFIRMED')),handover_date date NOT NULL,total_snags integer NOT NULL CHECK(total_snags>=0),critical_snags integer NOT NULL CHECK(critical_snags>=0),open_at_handover integer NOT NULL CHECK(open_at_handover>=0),average_closure_days numeric(12,2),reopened_snags integer NOT NULL CHECK(reopened_snags>=0),reopen_rate numeric(8,4)NOT NULL CHECK(reopen_rate>=0 AND reopen_rate<=100),snags_by_work_group jsonb NOT NULL CHECK(jsonb_typeof(snags_by_work_group)='array'),quality_explanation text NOT NULL CHECK(btrim(quality_explanation)<>''AND char_length(quality_explanation)<=3000),created_by uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,version_number)
);CREATE UNIQUE INDEX IF NOT EXISTS project_quality_closeout_one_confirmed_idx ON public.project_quality_closeout_versions(project_id)WHERE status='CONFIRMED';
CREATE OR REPLACE FUNCTION private.prevent_quality_closeout_mutation()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN RAISE EXCEPTION'PROJECT_QUALITY_CLOSEOUT_IMMUTABLE'USING ERRCODE='55000';END;$$;DROP TRIGGER IF EXISTS project_quality_closeout_immutable ON public.project_quality_closeout_versions;CREATE TRIGGER project_quality_closeout_immutable BEFORE UPDATE OR DELETE ON public.project_quality_closeout_versions FOR EACH ROW EXECUTE FUNCTION private.prevent_quality_closeout_mutation();
ALTER TABLE public.project_quality_closeout_versions ENABLE ROW LEVEL SECURITY;DROP POLICY IF EXISTS project_quality_closeout_select ON public.project_quality_closeout_versions;CREATE POLICY project_quality_closeout_select ON public.project_quality_closeout_versions FOR SELECT TO authenticated USING(public.can_access_project(project_id));REVOKE ALL ON TABLE public.project_quality_closeout_versions FROM PUBLIC,anon,authenticated,service_role;GRANT SELECT ON TABLE public.project_quality_closeout_versions TO authenticated;
CREATE OR REPLACE FUNCTION public.save_project_quality_closeout(p_project_id bigint,p_closeout_id uuid,p_quality_explanation text,p_confirm boolean,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE u uuid:=auth.uid();v_role text;req public.write_command_requests%ROWTYPE;handover date;total integer;critical integer;open_handover integer;avg_days numeric;reopened integer;rate numeric;groups jsonb;version_no integer;state text;result jsonb;
BEGIN SELECT upper(p.role)INTO v_role FROM public.profiles p WHERE p.id=u;IF u IS NULL OR v_role NOT IN('PM','ADMIN')OR public.can_write_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PROJECT_QUALITY_CLOSEOUT_FORBIDDEN'USING ERRCODE='42501';END IF;IF p_closeout_id IS NULL OR p_client_request_id IS NULL OR btrim(COALESCE(p_quality_explanation,''))=''OR char_length(p_quality_explanation)>3000 THEN RAISE EXCEPTION'INVALID_PROJECT_QUALITY_CLOSEOUT'USING ERRCODE='22023';END IF;INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(u,'project_closeout.quality.save',p_client_request_id,p_project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT*INTO req FROM public.write_command_requests WHERE actor_id=u AND operation='project_closeout.quality.save'AND client_request_id=p_client_request_id;IF req.response IS NOT NULL THEN RETURN req.response||jsonb_build_object('idempotentReplay',true);END IF;IF EXISTS(SELECT 1 FROM public.project_quality_closeout_versions WHERE project_id=p_project_id AND status='CONFIRMED')THEN RAISE EXCEPTION'PROJECT_QUALITY_CLOSEOUT_ALREADY_CONFIRMED'USING ERRCODE='55000';END IF;SELECT COALESCE(actual_construction_completion_date,actual_opening_date)INTO handover FROM public.projects WHERE id=p_project_id;IF handover IS NULL THEN RAISE EXCEPTION'QUALITY_CLOSEOUT_REQUIRES_HANDOVER_DATE'USING ERRCODE='55000';END IF;SELECT count(*)FILTER(WHERE status<>'CANCELLED'),count(*)FILTER(WHERE priority='CRITICAL'AND status<>'CANCELLED'),count(*)FILTER(WHERE status<>'CANCELLED'AND created_at::date<=handover AND(closed_at IS NULL OR closed_at::date>handover)),round(avg(EXTRACT(epoch FROM(closed_at-created_at))/86400.0)FILTER(WHERE status='CLOSED'),2)INTO total,critical,open_handover,avg_days FROM public.snags WHERE project_id=p_project_id;SELECT count(DISTINCT snag_id)INTO reopened FROM public.snag_events WHERE project_id=p_project_id AND(event_type='REOPENED'OR(previous_state->>'status'='CLOSED'AND new_state->>'status'<>'CLOSED'));rate:=CASE WHEN total=0 THEN 0 ELSE round(reopened::numeric*100/total,4)END;SELECT COALESCE(jsonb_agg(jsonb_build_object('workGroupId',z.work_group_id,'label',z.label,'mappingState',z.mapping_state,'snagCount',z.snag_count,'criticalCount',z.critical_count)ORDER BY z.snag_count DESC,z.label),'[]')INTO groups FROM(SELECT s.work_group_id,COALESCE(w.label,'Unmapped: '||s.discipline_code)label,CASE WHEN s.work_group_id IS NULL THEN'UNMAPPED_LEGACY'ELSE'MAPPED'END mapping_state,count(*)snag_count,count(*)FILTER(WHERE s.priority='CRITICAL')critical_count FROM public.snags s LEFT JOIN public.work_ontology_work_groups w ON w.ontology_version_id=s.work_ontology_version_id AND w.id=s.work_group_id WHERE s.project_id=p_project_id AND s.status<>'CANCELLED'GROUP BY s.work_group_id,w.label,s.discipline_code)z;SELECT COALESCE(max(version_number),0)+1 INTO version_no FROM public.project_quality_closeout_versions WHERE project_id=p_project_id;state:=CASE WHEN COALESCE(p_confirm,false)THEN'CONFIRMED'ELSE'DRAFT'END;INSERT INTO public.project_quality_closeout_versions VALUES(p_closeout_id,p_project_id,version_no,state,handover,total,critical,open_handover,avg_days,reopened,rate,groups,btrim(p_quality_explanation),u,now());result:=jsonb_build_object('qualityCloseoutId',p_closeout_id,'versionNumber',version_no,'status',state,'handoverDate',handover,'totalSnags',total,'criticalSnags',critical,'openAtHandover',open_handover,'averageClosureDays',avg_days,'reopenedSnags',reopened,'reopenRate',rate,'workGroupCount',jsonb_array_length(groups));UPDATE public.write_command_requests SET response=result,completed_at=now()WHERE id=req.id;RETURN result||jsonb_build_object('idempotentReplay',false);END;$$;
CREATE OR REPLACE FUNCTION public.get_project_quality_closeout(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$DECLARE x public.project_quality_closeout_versions%ROWTYPE;BEGIN IF auth.uid()IS NULL OR public.can_access_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PROJECT_QUALITY_CLOSEOUT_FORBIDDEN'USING ERRCODE='42501';END IF;SELECT*INTO x FROM public.project_quality_closeout_versions WHERE project_id=p_project_id ORDER BY version_number DESC LIMIT 1;RETURN jsonb_build_object('projectId',p_project_id,'hasCloseout',x.id IS NOT NULL,'closeout',CASE WHEN x.id IS NULL THEN NULL ELSE jsonb_build_object('qualityCloseoutId',x.id,'versionNumber',x.version_number,'status',x.status,'handoverDate',x.handover_date,'totalSnags',x.total_snags,'criticalSnags',x.critical_snags,'openAtHandover',x.open_at_handover,'averageClosureDays',x.average_closure_days,'reopenedSnags',x.reopened_snags,'reopenRate',x.reopen_rate,'snagsByWorkGroup',x.snags_by_work_group,'qualityExplanation',x.quality_explanation,'createdAt',x.created_at)END);END;$$;
REVOKE ALL ON FUNCTION private.prevent_quality_closeout_mutation()FROM PUBLIC,anon,authenticated,service_role;REVOKE ALL ON FUNCTION public.save_project_quality_closeout(bigint,uuid,text,boolean,uuid),public.get_project_quality_closeout(bigint)FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.save_project_quality_closeout(bigint,uuid,text,boolean,uuid),public.get_project_quality_closeout(bigint)TO authenticated;
COMMIT;
